<?php
session_start();if(!isset($_SESSION["studentsid"])){header("Location: ../index.php?msg=Please+log+in+as+Student");exit();}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$conn=$db->getConnection();$bookName=trim($_POST['bookName']??'');if($bookName===''){header("Location: student_dashboard.php?msg=No+book+name+provided");exit();}$term="%".$bookName."%";$stmt=$conn->prepare("SELECT ISBN,bookName,authorName,price,quantity FROM books WHERE LOWER(bookName) LIKE LOWER(?) ORDER BY bookName");$stmt->bind_param("s",$term);$stmt->execute();$result=$stmt->get_result();?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Search Results | LMS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="dashboard-page"><main class="wide-container"><header class="dashboard-header"><div><span class="eyebrow">Library Catalogue</span><h1>Search Results</h1><p>Results for “<?php echo htmlspecialchars($bookName);?>”.</p></div><a class="logout-link" href="../logout.php">Logout</a></header><section class="book-grid"><?php if($result->num_rows>0):while($row=$result->fetch_assoc()):?><article class="book-card"><span class="book-label">Library Book</span><h2><?php echo htmlspecialchars($row['bookName']);?></h2><p class="book-author">by <?php echo htmlspecialchars($row['authorName']);?></p><dl class="book-details"><div><dt>ISBN</dt><dd><?php echo htmlspecialchars($row['ISBN']);?></dd></div><div><dt>Price</dt><dd><?php echo htmlspecialchars($row['price']);?></dd></div><div><dt>Quantity</dt><dd><?php echo htmlspecialchars($row['quantity']);?></dd></div></dl></article><?php endwhile;else:?><div class="empty-state">No matching books were found.</div><?php endif;?></section><div class="page-actions"><a class="secondary-action" href="student_dashboard.php">← Back to Dashboard</a></div></main><?php $stmt->close();$db->closeConnection();?></body></html>